import React, { useEffect, useRef, useState } from "react";
import bgcover from "../Images/game_bg2.png";
import Play_Instructions from "./Play_Instructions";
import AudioPlayer from "./AudioPlayer";
import { Button, Dialog, ThemeProvider } from "@mui/material";
import Card from "./Card";
import "../style/stackcard.css";
import jsondata from "../json/synonym.json";
import Swal from "sweetalert2";
import { ToastContainer } from "react-toastify";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { useNavigate } from "react-router-dom";
import wrong_buzzer from "../assets/wrong_buzzer.mp3";
import correct_buzzer from "../assets/correct_buzzer.mp3";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import { DialogActions, Slide } from "@mui/material";
import bronze_medal from "../Images/bronze_medal.png";
import help from "../Images/help.png";
import exit from "../Images/exit.png";
import sad_face from "../Images/sad_face.png";
import arrayShuffle from "array-shuffle";
import "../App.css";
import wrongstickynote from "../Images/wrongstickynote.png";
import stickynote from "../Images/stickynote.png";
import whitestickynote from "../Images/whitestickynote.jpg";
import "../style/common.css";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import DialogContentText from "@mui/material/DialogContentText";
import { createTheme } from "@mui/material/styles";
import { red, lightGreen } from "@mui/material/colors";
import { useTranslation } from "react-i18next";

const LE_G01_Synonym = () => {
  const [openCards, setOpenCards] = useState([]);
  const [clearedCards, setClearedCards] = useState({});
  const [lockCards, setLockCards] = useState([]);
  const [shouldDisableAllCards, setShouldDisableAllCards] = useState(false);

  var [flag1, setFlag1] = useState(false);
  var [flag2, setFlag2] = useState(false);
  var [flag3, setFlag3] = useState(false);
  var [flag4, setFlag4] = useState(true);
  var [flag5, setFlag5] = useState(false);
  var [flag6, setFlag6] = useState(false);
  var [flag7, setFlag7] = useState(false);

  const [open1, setOpen1] = useState(false);
  var [heplok, setHeplok] = useState(false);

  var [levelcount, setLevelcount] = useState(0);
  var [wordcount, setWordcount] = useState(0);
  var [totalque, setTotalque] = useState(0);
  var [score, setScore] = useState(0);

  var [mainArr, setMainArr] = useState([]);
  var [shuffledmainArr, setShuffledMainArr] = useState([]);
  var [currentword, setCurrentword] = useState("");
  var [currentwordmeaning, setCurrentwordmeaning] = useState("");
  var [shuffledcurrentoparr, setShuffledcurrentoparr] = useState([]);
  var [currentcorroparr, setCurrentcorroparr] = useState([]);

  const navigate = useNavigate();
  const { t, i18n } = useTranslation();

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");

  useEffect(() => {
    console.log(
      "jsondata ==>",
      jsondata[levelcount],
      "length ==>",
      Object.keys(jsondata[levelcount])
    );

    let etc = [];
    for (var i = 0; i < Object.keys(jsondata[levelcount]).length; i++) {
      etc.push(jsondata[levelcount][i]);
    }

    mainArr = etc;
    setMainArr(mainArr);
    shuffledmainArr = arrayShuffle(mainArr);
    setShuffledMainArr(shuffledmainArr);
    console.log("shuffled mainArr ==>", shuffledmainArr);
    console.log(
      "shuffled mainArr word ==>",
      arrayShuffle(shuffledmainArr[wordcount].options)
    );

    let val = Object.keys(jsondata[levelcount]);
    setTotalque(val.length);
  }, []);

  useEffect(() => {
    if (wordcount < 10) {
      setCurrentword(shuffledmainArr[wordcount].word);
      setCurrentwordmeaning(shuffledmainArr[wordcount].meaning);
      shuffledcurrentoparr = arrayShuffle(shuffledmainArr[wordcount].options);
      setShuffledcurrentoparr(shuffledcurrentoparr);
      setCurrentcorroparr(shuffledmainArr[wordcount].correct_op);
      console.log("currentoparr", shuffledcurrentoparr);
      console.log(
        "currentcorroparr",
        jsondata[levelcount][wordcount].correct_op
      );
    } else {
      if (score >= 5) {
        setFlag5(true);
      } else {
        setFlag6(true);
      }
    }
  }, [wordcount]);

  useEffect(() => {
    if (lockCards.length === 3) {
      setTimeout(() => {
        // alert("lockedcards are 3")
        wordcount = wordcount + 1;
        setWordcount(wordcount);
        setLockCards([]);
        setOpenCards([]);
        setClearedCards([]);
        flag3 = false;
        setFlag3(flag3);
        flag4 = false;
        setFlag4(flag4);
        console.log("After completing 3 lock cards btn ==>", wordcount);

        let notMatched = []; // Array to store elements not found

        for (let i = 0; i < lockCards.length; i++) {
          let found = false;

          for (let j = 0; j < currentcorroparr.length; j++) {
            if (lockCards[i] === currentcorroparr[j]) {
              found = true;
              break;
            }
          }

          if (!found) {
            notMatched.push(lockCards[i]);
          }
        }

        foo();
        // setTimeout(foo, 2000)
        function foo() {
          // alert("foo called")
          if (notMatched.length === 0 && !flag4) {
            playSoundcorrect();
            Swal.fire({
              position: "top-center",
              icon: "success",
              title: "Nice",
              html: `You have selected all the correct synonym cards for the "<strong>${currentword}</strong>" word.`,
              showConfirmButton: true,
            });
            flag4 = true;
            setFlag4(flag4);
            flag3 = true;
            setFlag3(flag3);
            score = score + 1;
            setScore(score);
          } else {
            console.log("Elements not found:", notMatched);
            if (notMatched.length == 1) {
              playSoundwrong();
              Swal.fire({
                position: "top-center",
                icon: "error",
                title: "Incorrect",
                html: `
              <p>"${notMatched[0]}" is wrong synonym.</p>
              <p>The meaning of "<strong>${currentword}</strong>" is "<em>${currentwordmeaning}</em>"</p>
            `,
                showConfirmButton: true,
              }).then((result) => {
                if (result.isConfirmed) {
                  // Update lockCards state with currentcooparr
                  flag4 = true;
                  setFlag4(flag4);
                  // setLockCards(currentcorroparr);
                }
              });

              flag3 = true;
              setFlag3(flag3);
            } else if (notMatched.length == 2) {
              playSoundwrong();
              Swal.fire({
                position: "top-center",
                icon: "error",
                title: "Incorrect",
                html: `
              <p>"${notMatched[0]}" and "${notMatched[1]}" are wrong synonyms.</p>
              <p>The meaning of "<strong>${currentword}</strong>" is "<em>${currentwordmeaning}</em>"</p>
            `,
                showConfirmButton: true,
              }).then((result) => {
                if (result.isConfirmed) {
                  // Update lockCards state with currentcooparr
                  flag4 = true;
                  setFlag4(flag4);
                  // setLockCards(currentcorroparr);
                }
              });

              flag3 = true;
              setFlag3(flag3);
            } else if (notMatched.length == 3) {
              playSoundwrong();
              Swal.fire({
                position: "top-center",
                icon: "error",
                title: "Incorrect",
                html: `
              <p>"All kept words are wrong.</p>
              <p>The meaning of "<strong>${currentword}</strong>" is "<em>${currentwordmeaning}</em>"</p>
            `,
                showConfirmButton: true,
              }).then((result) => {
                if (result.isConfirmed) {
                  // Update lockCards state with currentcooparr
                  flag4 = true;
                  setFlag4(flag4);
                  // setLockCards(currentcorroparr);
                }
              });

              flag3 = true;
              setFlag3(flag3);
            }
          }
        }
      }, 1000);
    }
  }, [lockCards]);

  const Transition = React.forwardRef(function Transition(props, ref) {
    return <Slide direction="down" ref={ref} {...props} />;
  });

  const theme = createTheme({
    palette: {
      primary: {
        main: red[500],
        contrastText: "#000000",
      },
      secondary: {
        main: lightGreen[500],
        contrastText: "#000000",
      },
    },
  });
  const audioRefwrong = useRef(null);
  const audioRefcorrect = useRef(null);

  const playSoundwrong = () => {
    audioRefwrong.current.play();
  };

  const playSoundcorrect = () => {
    audioRefcorrect.current.play();
  };

  const handleClose1 = () => {
    setOpen1(false);
  };

  const handleHelp = () => {
    setOpen1(true);
    setHeplok(true);

    ReactGA.event({
      action: "English Synonym | CDAC-OlabsNxtG-En-22 | Clicked on (i) button",
      category: "English CDAC-OlabsNxtG-En-22 | level-1 (i) button clicked",
      label:
        "English CDAC-OlabsNxtG-En-22 | level-1 (i) button to to view the instructions for game.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Level-1 (i) button",
      "Clicked",
      "Level-1 (i) button clicked to view the instructions for game."
    );
  };

  const handleCardClick = (index) => {
    console.log("called handleclick", index);
    setOpenCards([index]);
  };

  const checkIsFlipped = (index) => {
    console.log("checkIsFlipped called", openCards.includes(index));
    return openCards.includes(index);
  };

  const checkIsInactive = (card) => {
    console.log("In checkIsInactive =>", clearedCards[card]);
    return Boolean(clearedCards[card]);
  };

  useEffect(() => {
    console.log("useEffect called for openCards", openCards);
    let timeout = null;
    if (openCards.length === 1) {
      // timeout = setTimeout(evaluate, 300);
      flag1 = true;
      setFlag1(flag1);
    }
    return () => {
      clearTimeout(timeout);
    };
  }, [openCards]);

  const handleKeep = () => {
    console.log("In handle keep button openCards is ==>", openCards);
    var locked = [];
    flag2 = true;
    setFlag2(flag2);
    console.log("cards[openCards] ==>", shuffledcurrentoparr[openCards]);
    flag1 = false;
    setFlag1(flag1);
    if (lockCards.length < 3) {
      if (!lockCards.includes(shuffledcurrentoparr[openCards])) {
        ReactGA.event({
          action:
            "English Synonym | CDAC-OlabsNxtG-En-22 | Clicked on Keep card button",
          category:
            "English CDAC-OlabsNxtG-En-22 | level-1 Keep card button clicked",
          label:
            "English CDAC-OlabsNxtG-En-22 | level-1 Keep card button to keep the card.",
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          'Level-1 "Keep card" button',
          "Clicked",
          'Level-1 "Keep card" button to keep the card'
        );

        setLockCards((prevLocked) => {
          // Create a new array by spreading the previous locked cards and adding the new one
          return [...prevLocked, shuffledcurrentoparr[openCards]];
        });
      } else {
        toast.error(
          "This card is already added in kept cards! Please select another card",
          {
            position: "top-center",
          }
        );
      }
    } else {
      toast.error("You can keep only three cards", {
        position: "top-center",
      });
    }
  };

  const handleClick = () => {
    document.querySelector("ul.cards").classList.toggle("transition");
  };

  const handleExit = () => {
    flag7 = true;
    setFlag7(flag7);

    ReactGA.event({
      action: "English Synonym | CDAC-OlabsNxtG-En-22 | Clicked on Exit button",
      category: "English CDAC-OlabsNxtG-En-22 | level-1 Exit button clicked",
      label:
        "English CDAC-OlabsNxtG-En-22 | level-1 Exit button to exit from level 1.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Exit" button',
      "Clicked",
      'Level-1 "Exit" button to exit from level 1'
    );
  };

  const handletolevel2 = () => {
    setFlag6(false);
    ReactGA.event({
      action:
        'English Synonym | CDAC-OlabsNxtG-En-22 | Clicked on "Proceed to level 2" button',
      category:
        'English CDAC-OlabsNxtG-En-22 | "Proceed to level 2" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-22 | "Proceed to level 2" button clicked and level 2 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Proceed to level 2" button',
      "Clicked",
      '"Proceed to level 2" button clicked and level 2 started'
    );

    navigate("/launchpage/englishactivity/synonym/level2");
  };

  const handlerestart = () => {
    setFlag6(false);

    ReactGA.event({
      action:
        'English Synonym | CDAC-OlabsNxtG-En-22 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-22 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-22 | "Restart" button clicked and level 1 restarted',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 1 restarted'
    );

    window.location.reload();
  };

  const handleYes = () => {
    setFlag7(false);
    navigate("/");
  };

  const handleCancel = () => {
    setFlag7(false);
  };

  return (
    <div
      className="row d-flex justify-content-center"
      style={{
        height: "100%",
        width: "100%",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        marginLeft: "auto",
        marginRight: "auto",
        backgroundRepeat: "no-repeat",
        backgroundSize: "cover",
        backgroundColor: "lightgrey",
      }}
    >
      <Play_Instructions
        handleClose1={handleClose1}
        open1={open1}
        setOpen1={setOpen1}
        heplok={heplok}
      />

      <div
        className="d-flex justify-content-between "
        style={{
          // height: "10%",
          backgroundColor: "lightgrey",
          borderRadius: "14px",
        }}
      >
        <div className="">
          <div
            className="text-center d-flex justify-content-center align-items-center"
            style={{ border: "1px" }}
          >
            <p
              className=""
              style={{
                background: "FF8E8F",
                fontSize: "clamp(12px, 3vw, 12px)",
                padding: "7px",
                marginTop: "15px",
                border: "3px solid #006216",
                borderRadius: "9px",
                opacity: "1",
                color: "#006216",
              }}
            >
              <strong>
                Score: {score}/{totalque}
              </strong>
            </p>
          </div>
        </div>
        <div className="">
          <div
            className=" text-center d-flex justify-content-center align-items-center"
            style={{ border: "1px", textAlign: "center" }}
          >
            <p
              className="bg-light"
              style={{
                background: "FF8E8F",
                fontSize: "clamp(12px, 3vw, 14px)",
                padding: "7px",
                marginTop: "15px",
                font: "normal normal Montserrat",
                letterSpacing: "0px",
                color: "#030000",
                opacity: "1",
              }}
            >
              <strong>Word:- </strong>
              <strong
                style={{
                  font: "normal normal Montserrat",
                  letterSpacing: "0px",
                  color: "#002445",
                  opacity: "1",
                  fontSize: "clamp(12px, 3vw, 15px)",
                }}
              >
                {" "}
                {currentword}
              </strong>
            </p>
          </div>
        </div>
        <div className="d-flex justify-content-around">
          <div
            className="rounded-4 text-center"
            style={{ border: "1px", marginRight: "10px" }}
          >
            <AudioPlayer />
          </div>
          <div
            className=" text-center "
            variant="contained"
            onClick={handleHelp}
            style={{ marginTop: "15px" }}
          >
            <img
              style={{ marginTop: "10px", height: "26px", width: "26px" }}
              src={help}
              title={t("help")}
            ></img>
          </div>
          <div
            className=" text-center "
            variant="contained"
            style={{ border: "1px", marginLeft: "12px", marginTop: "15px" }}
          >
            <img
              style={{ marginTop: "10px" }}
              src={exit}
              onClick={handleExit}
              title={t("exit")}
            ></img>
          </div>
        </div>
      </div>

      <div
        className="row  d-flex "
        style={{
          height: "90%",
          overflow: "auto",
          backgroundColor: "lightgray",
          backgroundImage: "url(" + bgcover + ")",
          backgroundSize: "cover",
          borderRadius: "14px",
        }}
      >
        <div className="col-lg-6 col-md-6 col-sm-12  justify-content-center align-items-center">
          <div
            className="container col bg-opacity-50 bg-white "
            style={{ marginTop: "5vh" }}
          >
            {shuffledcurrentoparr.map((card, index) => {
              return (
                <Card
                  key={index}
                  card={card}
                  index={index}
                  isDisabled={shouldDisableAllCards}
                  isInactive={checkIsInactive(card)}
                  isFlipped={checkIsFlipped(index)}
                  onClick={handleCardClick}
                  isFreeze={flag2}
                />

                // <Card
                //   key={index}
                //   card={card}
                //   handleCardClick={handleCardClick}
                //   flipped={checkIsFlipped(index)}
                //   disabled={shouldDisableAllCards}
                // />
              );
            })}
          </div>

          <div
            className="restart col d-flex justify-content-around"
            style={{ marginTop: "10px", display: "none" }}
          >
            {flag1 ? (
              <Button
                onClick={handleKeep}
                color="primary"
                variant="contained"
                style={{
                  background: "#B35EF4 0% 0% no-repeat padding-box",
                  opacity: "1",
                }}
              >
                Keep Card
              </Button>
            ) : (
              ""
            )}
          </div>
        </div>

        <div className="col-lg-6 col-md-6 col-sm-12  justify-content-center align-items-center">
          <div
            className="row-md-auto "
            style={{ display: "flex", flexWrap: "wrap", marginTop: "15vh" }}
          >
            <ul
              className="cards justify-content-center align-items-center"
              onClick={handleClick}
              style={{ height: "20vh" }}
            >
              {lockCards.map((item, index) => {
                const isCorrect = currentcorroparr.includes(item);
                const backgroundImage = isCorrect
                  ? flag4
                    ? `url(${stickynote})`
                    : `url(${whitestickynote})`
                  : flag4
                  ? `url(${wrongstickynote})`
                  : `url(${whitestickynote})`;

                return (
                  <li
                    key={index}
                    className="card"
                    style={{
                      backgroundImage: backgroundImage,
                      backgroundSize: "cover",
                      backgroundPosition: "center",
                    }}
                  >
                    <div className="content">{item}</div>
                  </li>
                );
              })}
            </ul>
          </div>
        </div>
      </div>

      {flag5 ? (
        <Dialog
          className="animate__animated animate__zoomIn"
          open={flag5}
          hideBackdrop
          style={{ backgroundColor: "rgba(0, 0, 0, 0.5)" }}
        >
          <DialogTitle
            className="text-center text-white fw-bolder fs-4"
            style={{ backgroundColor: "#FFBF00" }}
          >
            Result
          </DialogTitle>
          <DialogContent className="bg-transparent bg-opacity-10">
            <div
              className=""
              style={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                marginBottom: "20px",
              }}
            >
              <img
                src={bronze_medal}
                alt="bronze Medal"
                style={{
                  maxWidth: "100%",
                  maxHeight: "100%",
                  width: "auto",
                  height: "auto",
                }}
              />
            </div>
            <h3 style={{ textAlign: "center" }}>
              <strong>Congratulations!!</strong>
            </h3>
            <p
              style={{
                textAlign: "center",
                fontSize: "clamp(12px, 2vw, 22px)",
              }}
            >
              {" "}
              You have won Bronze medal.
            </p>
            <p
              style={{
                textAlign: "center",
                fontSize: "clamp(12px, 2vw, 22px)",
              }}
            >
              {" "}
              Your score is {score}.
            </p>
            <p
              style={{
                textAlign: "center",
                fontSize: "clamp(12px, 2vw, 22px)",
              }}
            >
              Now you can proceed for level 2.
            </p>
          </DialogContent>

          <DialogActions className="d-flex justify-content-center">
            <Button
              variant="contained"
              color="success"
              size="small"
              onClick={handletolevel2}
            >
              Proceed to level 2
            </Button>
          </DialogActions>
        </Dialog>
      ) : null}

      {flag6 ? (
        <Dialog
          className="animate__animated animate__zoomIn"
          open={flag6}
          hideBackdrop
          style={{ backgroundColor: "rgba(0, 0, 0, 0.5)" }}
        >
          <DialogTitle
            className="text-center text-white fw-bolder fs-4"
            style={{ backgroundColor: "#FFBF00" }}
          >
            Result
          </DialogTitle>
          <DialogContent className="bg-transparent bg-opacity-10">
            <div
              className=""
              style={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                marginBottom: "20px",
              }}
            >
              <img
                src={sad_face}
                alt="sad face"
                style={{
                  maxWidth: "100%",
                  maxHeight: "100%",
                  width: "auto",
                  height: "auto",
                }}
              />
            </div>
            <h3 style={{ textAlign: "center" }}>
              <strong>Level 1 Fail</strong>
            </h3>
            <p
              style={{
                textAlign: "center",
                fontSize: "clamp(12px, 2vw, 22px)",
              }}
            >
              {" "}
              Your score is {score}.
            </p>
            <p
              style={{
                textAlign: "center",
                fontSize: "clamp(12px, 2vw, 22px)",
              }}
            >
              You need to answer atleast 5 correct synonym words.
            </p>
            <p style={{ textAlign: "center" }}>
              You can try to clear level 1 by clicking on "Restart" button.
            </p>
          </DialogContent>

          <DialogActions className="d-flex justify-content-center">
            <Button
              variant="contained"
              color="success"
              size="small"
              onClick={handlerestart}
            >
              Restart
            </Button>
          </DialogActions>
        </Dialog>
      ) : null}

      {flag7 ? (
        <Dialog
          open={flag7}
          TransitionComponent={Transition}
          keepMounted
          onClose={handleYes}
          aria-describedby="alert-dialog-slide-description"
        >
          <DialogContent>
            <DialogContentText
              id="alert-dialog-slide-description"
              style={{ color: "#1A0330" }}
            >
              Are you sure you want to exit?
            </DialogContentText>
          </DialogContent>
          <DialogActions style={{ justifyContent: "space-around" }}>
            <ThemeProvider theme={theme}>
              <Button
                variant="contained"
                color="secondary"
                size="small"
                onClick={handleYes}
              >
                Yes
              </Button>
              <Button
                variant="contained"
                color="primary"
                size="small"
                onClick={handleCancel}
              >
                Cancel
              </Button>
            </ThemeProvider>
          </DialogActions>
        </Dialog>
      ) : null}

      <ToastContainer />

      <audio ref={audioRefcorrect} src={correct_buzzer}></audio>
      <audio ref={audioRefwrong} src={wrong_buzzer}></audio>
    </div>
  );
};

export default LE_G01_Synonym;
