import React, { useState } from "react";
import ReactPlayer from "react-player";
import song from "../assets/game_bg_music2.mp3";
import { VolumeOffOutlined, VolumeUpOutlined } from "@mui/icons-material";
import { Button } from "@mui/material";
import soundOn from "../Images/soundOn.png";
import soundOff from "../Images/soundOff.png";
import { useTranslation } from "react-i18next";

function AudioPlayer() {
  const [isMuted, setIsMuted] = useState(false);
  const { t, i18n } = useTranslation();

  const toggleMute = () => {
    setIsMuted((prevIsMuted) => !prevIsMuted);
  };

  return (
    <div className=" d-flex justify-content-center align-items-center">
      <ReactPlayer
        url={song}
        loop={true}
        playing={!isMuted}
        muted={false}
        width="10px"
        height="10px"
        volume="0.3"
      />
      {/* <Button
        onClick={toggleMute}
        className="rounded-5"
        variant="contained"
        color="secondary"
        size="small"
        style={{marginTop:"15px"}}
      >
      
       {isMuted ? <VolumeOffOutlined /> : <VolumeUpOutlined />}
       
     </Button> */}

      {isMuted ? (
        <img
        src={soundOff}
        onClick={toggleMute}
        className="rounded-5"
        variant="contained"
        color="secondary"
        size="small"
        style={{ marginTop: "24px" }}
        title={t("unmute")}
      ></img>
      ) : (
      <img
        src={soundOn}
        onClick={toggleMute}
        className="rounded-5"
        variant="contained"
        color="secondary"
        size="small"
        style={{ marginTop: "24px" }}
        title={t("mute")}
      ></img>
      )}


      {/* <img
        src={soundOn}
        onClick={toggleMute}
        className="rounded-5"
        variant="contained"
        color="secondary"
        size="small"
        style={{marginTop:"15px"}}
        >
        {isMuted ? <VolumeOffOutlined /> : <VolumeUpOutlined />}
        </img> */}

    </div>
  );
}

export default AudioPlayer;
